-- Generated by scripts/hourly-events-sql.mjs. Do not edit by hand.
-- Hourly events (20 Oct 2026, the owner): the switch. A new event every hour, on the hour: 55 minutes of play, then 5 minutes in which
-- the prizes are handed out. One goal per league, about a fifth of the 5-hour medium goal. Diamonds only: 8 / 5 / 3 for the first
-- three in a league, 1 for every other finisher, +3 each when 3 or more of one Farm family finish. They count in events_finished.
-- Run it after the site and farm-api of this change are live, while no event runs; best at hh:00-hh:04 so the first event starts at
-- once. Save the harvest_event_% definitions and today's live_events rows first (no PITR). One transaction: any failed check rolls
-- all of it back. Running it twice changes nothing.
-- Pause for a release:  select public.harvest_event_pause(date_trunc('hour',now())+interval '2 hours');   (run during hh:xx: the next
-- hour has no event)    End the pause:  select public.harvest_event_pause(null);    Stop events:  select public.harvest_event_pause('infinity');
begin;
set local lock_timeout='5s';
do $guard$
declare want jsonb:='{"harvest_event_board(uuid)":["c509587a78de0cdc576cd6681ba9a29f"],"harvest_event_claim(uuid,uuid)":["de2cdc930a667bc9c80f3737fca9929c"],"harvest_event_league(integer)":["ea594ad4aeb110d5858de5cdaf68ddbe"],"harvest_event_league_for(integer,jsonb,smallint)":["72ba9cc06862bab8a5778cecd96fbaa7"],"harvest_event_pick(bigint)":["56d9b813f0b9223c59251ff07d0bbc28","a4354b4070af10908e1e609720cba26d"],"harvest_event_progress()":["4681019789851e424d9a12f74f843077"],"harvest_event_schedule()":["d280ae236ddae469437e80ef2bade5d9","aecdec923a2d0ef6fd71eb320e1b3482","3d8632d66217916f3a9d18a74d340577"],"harvest_event_settle(uuid)":["b73dea6778379f0bc6503f7bccad1870","1fd63cef297e5f96636fe7da62596b13"],"harvest_event_validate()":["588cad3b5889d187cfcff6f0f05182fe","15a89d91355e859133cecff10277a0fc"]}';
 fn text; have text;
begin
 -- Only while nothing runs: no event ever mixes the old and the new rules.
 if exists(select 1 from public.live_events where active and starts_at<=now() and ends_at>now()) then
  raise exception 'An event is running. Run this file while no event runs.'; end if;
 if to_regprocedure('public.harvest_event_league_for(integer,jsonb,smallint)') is null then
  raise exception 'Run World 2 leagues Part B (supabase/world-two-leagues-b.sql) first.'; end if;
 for fn in select jsonb_object_keys(want) loop
  select md5(prosrc) into have from pg_proc where oid=to_regprocedure('public.'||fn);
  if have is null or not (want->fn ? have) then raise exception 'public.% is not the one this file expects (md5 %); read the live definition first', fn, have; end if;
 end loop;
 -- Events that have ended are settled first, with the functions as they are now.
 perform public.harvest_event_settle(id) from public.live_events where ends_at<=now() and settled_at is null;
end $guard$;

-- 1. The table check allows a 55-minute event (it was 1 to 12 hours). farm-api keeps 1 to 12 hours for an event made by hand.
alter table public.live_events drop constraint if exists live_events_check;
alter table public.live_events add constraint live_events_check check (ends_at>=starts_at+interval '30 minutes' and ends_at<=starts_at+interval '12 hours');

-- 2. The pause switch: one row, only postgres and service_role (no policies), like chat_config. Not a player table.
create table if not exists public.event_config(id boolean primary key default true check (id), paused_until timestamptz,
 updated_at timestamptz not null default now());
insert into public.event_config(id) values (true) on conflict do nothing;
alter table public.event_config enable row level security;
revoke all on public.event_config from anon, authenticated;
create or replace function public.harvest_event_pause(p_until timestamptz)
 returns text language plpgsql set search_path to '' as $function$
declare removed integer; running timestamptz;
begin
 if p_until is not null and p_until<=now() then raise exception 'Give a time in the future, or null to end the pause.'; end if;
 update public.event_config set paused_until=p_until,updated_at=now() where id;
 -- Events made ahead inside the pause go now (none has a row: progress only counts started events).
 delete from public.live_events e where e.created_by is null and e.settled_at is null and e.starts_at>now() and e.starts_at<p_until
  and not exists(select 1 from public.live_event_players lp where lp.event_id=e.id);
 get diagnostics removed=row_count;
 select max(ends_at) into running from public.live_events where active and starts_at<=now() and ends_at>now();
 if p_until is null then perform public.harvest_event_schedule(); end if;
 return case when p_until is null then 'Events are on again. The next one starts on the hour.'
  else format('No event starts before %s UTC. %s event(s) made ahead removed.%s',to_char(p_until at time zone 'UTC','YYYY-MM-DD HH24:MI'),removed,
   case when running is null then '' else format(' The running event ends at %s UTC.',to_char(running at time zone 'UTC','HH24:MI')) end) end;
end $function$;
revoke all on function public.harvest_event_pause(timestamptz) from public, anon, authenticated;
grant execute on function public.harvest_event_pause(timestamptz) to service_role;

-- 3. The check on events, with the rules of an hourly event's prizes.
create or replace function public.harvest_event_validate()
 returns trigger language plpgsql set search_path to '' as $function$
declare objective jsonb; k text;
begin
 perform pg_advisory_xact_lock(724919);
 if TG_OP='UPDATE' and old.starts_at<=now() and (new.title<>old.title or new.description<>old.description or new.starts_at<>old.starts_at or new.ends_at<>old.ends_at or new.objectives<>old.objectives or new.rewards<>old.rewards) then raise exception 'Started events are frozen. Create a new event to change the rules.'; end if;
 if new.active and new.ends_at>now() and exists(select 1 from public.live_events e where e.id<>new.id and e.active and e.starts_at<new.ends_at and e.ends_at>new.starts_at) then raise exception 'Active events cannot overlap.'; end if;
 if jsonb_typeof(new.objectives)<>'array' or jsonb_array_length(new.objectives) not between 1 and 4 then raise exception 'Choose 1–4 objectives.'; end if;
 for objective in select value from jsonb_array_elements(new.objectives) loop
  if coalesce(objective->>'stat','') not in ('harvested','produced','watered','tended','chores','deliveries','harvest_wheat','harvest_corn','harvest_lettuce','harvest_barley','harvest_greenbeans','harvest_cabbage','made_eggs','planted','sold','earned','coins_spent','diamonds_spent','activities','upgrades','made_feed','made_milk','made_cheese','made_flour','fertilized','harvest_cauliflower','made_grainmeal','made_bread','parallel_batches','boosts_used','activity_rounds','sold_wheat','made_salad','made_fertilizer','sold_eggs','made_vegetables','made_pickles','made_oil','made_beangratin','made_applepie','made_orchardsalad','made_pie','made_stew','sold_cheese','tractor','glasshouse_batches','made_berrysmoothie','made_applecompote','made_pickledbeans','made_truffleomelette','made_berrycheesecake','made_applejuice','made_orchardjuice','made_berrypreserves','made_truffles','made_honey','made_wool','made_squashsoup','made_yarn','made_cloth','made_goatmilk','made_goatcheese','made_candles','made_cider','made_cherryjam','valley_baskets','made_stone','made_ironore','made_timber','made_packedlunch','village_batches','made_plank','village_requests','lake_fish','made_clay','made_potatoes','made_ironbar','made_pickaxe','made_rooftile','made_flax','made_lavender','made_linen','made_builderscrate','made_lavendersoap','made_scentedsachet','made_silvercandlestick','made_rubyring') or coalesce((objective->>'target')::integer,0) not between 1 and 10000 then raise exception 'Invalid event objective.'; end if;
 end loop;
 if (select count(distinct value->>'stat') from jsonb_array_elements(new.objectives))<>jsonb_array_length(new.objectives) then raise exception 'Objectives must be unique.'; end if;
 foreach k in array array['coins','diamondMin','diamondMax','participantStep','poolCap'] loop
  if not new.rewards ? k or jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
 end loop;
 if (new.rewards->>'coins')::integer not between 0 and 300 or (new.rewards->>'diamondMin')::integer not between 0 and 1 or (new.rewards->>'diamondMax')::integer not between 1 and 3 or (new.rewards->>'participantStep')::integer not between 10 and 1000 or (new.rewards->>'poolCap')::integer not between 0 and 200 then raise exception 'Reward settings exceed safe limits.'; end if;
 if new.rewards ? 'podium' then
  if jsonb_typeof(new.rewards->'podium')<>'array' or jsonb_array_length(new.rewards->'podium')<>3
   -- (a case, not an or: SQL does not promise to stop before casting a non-number)
   or exists(select 1 from jsonb_array_elements(new.rewards->'podium') d where case when jsonb_typeof(d)='number' then d::text::numeric<>trunc(d::text::numeric) or d::text::numeric not between 0 and 25 else true end)
   then raise exception 'Podium diamonds must be 3 whole numbers from 0 to 25.'; end if;
  foreach k in array array['finisher','familyFinishers','familyDiamonds'] loop
   if not new.rewards ? k or jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
  end loop;
  if (new.rewards->>'finisher')::integer not between 0 and 3 or (new.rewards->>'familyFinishers')::integer not between 2 and 10
   or (new.rewards->>'familyDiamonds')::integer not between 0 and 5 or (new.rewards->>'coins')::integer<>0
   then raise exception 'Reward settings exceed safe limits.'; end if;
 end if;
 return new;
end $function$;

