 grp int:=(n%5)::int; lg int; r bigint; pool jsonb; kind jsonb; title jsonb; leagues jsonb:='[]'::jsonb;
begin
 -- The kind of play is the same for everyone this hour (fields, crops, buildings, market, helping out; in the village mine and
 -- forest, fields and kitchens, workshops, market square, around the village). 24 is not a multiple of 5, so an hour of the day
 -- gets another kind every day.
 for lg in 0..jsonb_array_length(pools)-1 loop
  pool:=pools->lg->grp;
  r:=abs(hashtextextended('harvest-hour-event:'||n||':'||lg,0));
  kind:=pool->((r%jsonb_array_length(pool))::int);
  title:=kind->'titles'->(((r/7)%jsonb_array_length(kind->'titles'))::int);
  leagues:=leagues||jsonb_build_array(jsonb_build_object('title',title->>0,'description',title->>1,
   'objectives',jsonb_build_array(jsonb_build_object('stat',kind->>'stat','target',(kind->>'target')::int))));
 end loop;
 -- The event's own title and goal are the Sprout League's: admin screens and any older reader keep working.
 return jsonb_build_object('title',leagues->0->>'title','description',leagues->0->>'description','objectives',leagues->0->'objectives','leagues',leagues);
end $function$;

-- 5. Settle: the event's own prizes. An hourly event (rewards with podium) pays 8 / 5 / 3 and 1 diamonds and no coins; an older
-- event is paid as Part B did.
create or replace function public.harvest_event_settle(p_event uuid)
 returns void language plpgsql set search_path to '' as $function$
declare e public.live_events; n integer; per_player integer; budget integer; hour boolean; fam_n integer; fam_d integer; fam_c integer;
begin
 select * into e from public.live_events where id=p_event for update;
 if not found or e.ends_at>now() or e.settled_at is not null then return; end if;
 -- The prizes are the event's own (rewards, 20 Oct 2026): an hourly event carries podium and finisher diamonds and pays no
 -- coins; an older event without them keeps the rules it was made with (event-podium-2026-10-08.sql, world-two-leagues-b.sql).
 hour:=e.rewards ? 'podium';
 fam_n:=coalesce((e.rewards->>'familyFinishers')::integer,3);fam_d:=coalesce((e.rewards->>'familyDiamonds')::integer,3);fam_c:=case when hour then 0 else 200 end;
 -- The league of every farmer in the event, by their level now (1 Oct 2026), and then whether they finished their league's goals
 -- (live-event-league-goals.sql; an event without per-league goals uses its own for everyone). Within the leagues the event was made
 -- with, and at most the Valley Legends for a farmer who first counted below level 100 (world 1; 20 Oct 2026).
 update public.live_event_players p set league=public.harvest_event_league_for(s.level,e.leagues,p.world)
  from public.player_stats s where p.event_id=p_event and s.player_id=p.player_id;
 update public.live_event_players set league=0 where event_id=p_event and league is null;
 update public.live_event_players p set qualified=(not exists(select 1 from jsonb_array_elements(coalesce(e.leagues->p.league->'objectives',e.objectives)) o where coalesce((p.progress->>(o->>'stat'))::integer,0)<(o->>'target')::integer)) where event_id=p_event;
 select count(*) into n from public.live_event_players where event_id=p_event and qualified;
 per_player:=least((e.rewards->>'diamondMax')::integer,(e.rewards->>'diamondMin')::integer+floor(sqrt(n::numeric/(e.rewards->>'participantStep')::integer))::integer);
 budget:=least((e.rewards->>'poolCap')::integer,n*per_player);
 -- Completed players are ordered by completion time within their league, UUID as deterministic tie-break. The first three of each
 -- league also win a podium prize on top (+2000, +1000, +500 coins) and every later finisher +100 coins; the event's coins and the
 -- podium coins are × the league's number (1–5), 8 for the Valley Legends, 10–20 for the village leagues. Diamonds are a fixed 25, 15, 10 and 3 in every league
 -- (7 Oct 2026; 50, 30, 20 and 5 before), however many finished in the league (8 Oct 2026; on 7 Oct only with 4 or more).
 -- All of that is for an event from before 20 Oct 2026. An hourly event pays the diamonds of its own rewards (podium, then finisher
 -- from 4th place on) and no coins.
 with ranked as (select player_id,league,row_number() over(partition by league order by last_at,player_id) as rank from public.live_event_players where event_id=p_event and qualified)
 update public.live_event_players p set
  coins=case when hour then 0 else ((e.rewards->>'coins')::integer+(case r.rank when 1 then 2000 when 2 then 1000 when 3 then 500 else 100 end))*(array[1,2,3,4,5,8,10,12,14,16,18,20])[r.league+1] end,
  diamonds=case when hour then coalesce((e.rewards->'podium'->>(r.rank::integer-1))::integer,(e.rewards->>'finisher')::integer)
   else (case r.rank when 1 then 25 when 2 then 15 when 3 then 10 else 3 end) end
  from ranked r where p.event_id=p_event and p.player_id=r.player_id;
 -- The family bonus (27 Sep 2026): fam_n or more finishers from one family in this event each get fam_d diamonds, and 200 coins on an
 -- event from before 20 Oct 2026 (+5 diamonds until 7 Oct 2026).
 with fam as (select m.family_id,lp.player_id from public.live_event_players lp
   join public.family_members m on m.player_id=lp.player_id and m.left_at is null
   join public.families f on f.id=m.family_id and f.deleted_at is null
   where lp.event_id=p_event and lp.qualified),
  big as (select family_id from fam group by family_id having count(*)>=fam_n)
 update public.live_event_players p set coins=p.coins+fam_c,diamonds=p.diamonds+fam_d
  from fam where fam.family_id in (select family_id from big) and p.event_id=p_event and p.player_id=fam.player_id;
 update public.live_events set settled_at=now(),participants=(select count(*) from public.live_event_players where event_id=p_event),qualified=n,diamond_pool=budget where id=p_event;
 -- Village events (20 Oct 2026): the events finished in a village league count in village_events_finished too. Both are recounts.
 update public.player_stats s set events_finished=(select count(*) from public.live_event_players lp where lp.player_id=s.player_id and lp.qualified),
  village_events_finished=(select count(*) from public.live_event_players lp where lp.player_id=s.player_id and lp.qualified and lp.league>=6)
  where s.player_id in (select player_id from public.live_event_players where event_id=p_event and qualified);
end $function$;

-- 6. Schedule: an event every hour, the current hour and 2 ahead.
create or replace function public.harvest_event_schedule()
 returns void language plpgsql set search_path to '' as $function$
declare
 rewards constant jsonb:='{"coins":0,"diamondMin":1,"diamondMax":1,"participantStep":25,"poolCap":50,"podium":[8,5,3],"finisher":1,"familyFinishers":3,"familyDiamonds":3}';
 slot bigint:=floor(extract(epoch from now())/3600)::bigint;
 paused timestamptz; ended uuid; n bigint; starts timestamptz; event_id uuid; t jsonb;
begin
 for ended in select e.id from public.live_events e where e.ends_at<=now() and e.settled_at is null loop
  perform public.harvest_event_settle(ended);
 end loop;
 select c.paused_until into paused from public.event_config c where c.id;
 -- Automatic events nobody has a row in that have not started: the 6-hour ones from before 20 Oct 2026, and hourly ones inside a pause.
 delete from public.live_events e where e.created_by is null and e.settled_at is null and e.starts_at>now()
  and (e.ends_at-e.starts_at>interval '55 minutes' or e.starts_at<paused)
  and not exists(select 1 from public.live_event_players lp where lp.event_id=e.id);
 for n in slot..slot+2 loop
  starts:=to_timestamp(n*3600);
  -- Never an event with under 50 minutes to play (after a pause or a late run), never inside a pause.
  continue when starts<now()-interval '5 minutes' or starts<paused;
  event_id:=md5('harvest-hour-event:'||n)::uuid;
  continue when exists(select 1 from public.live_events e where e.id=event_id);
  t:=public.harvest_event_pick(n);
  begin
   insert into public.live_events(id,title,description,starts_at,ends_at,active,objectives,rewards,created_by,leagues)
   values(event_id,t->>'title',t->>'description',starts,starts+interval '55 minutes',true,t->'objectives',rewards,null,t->'leagues');
  exception
   -- An operator's own active event already holds this time, or a parallel run just created the same slot.
   when raise_exception or unique_violation then null;
  end;
 end loop;
end $function$;

-- 7. The progress trigger reads live_events on every farm save; the table now grows by 24 rows a day. Unsettled rows stay few.
create index if not exists live_events_open on public.live_events (starts_at) where settled_at is null;

-- 8. The two 6-hour events of 20 Oct 2026 that the pause left inactive (12:00 and 18:00 UTC, nobody in them) go, so they never show
-- in Recent events.
delete from public.live_events e where e.created_by is null and not e.active and e.starts_at>='2026-10-20 12:00+00'
 and e.ends_at-e.starts_at>interval '55 minutes' and not exists(select 1 from public.live_event_players lp where lp.event_id=e.id);

-- 9. The cron job every 5 minutes, so the run at :55 hands out the prizes in the gap (job 2, updated by name).
select cron.schedule('harvest-event-schedule','*/5 * * * *','select public.harvest_event_schedule()');

-- 10. The first events: at hh:00-hh:05 this hour's starts at once; otherwise the first starts at the next :00.
select public.harvest_event_schedule();

-- 11. Self-check of the pick: 500 hours from now, every one with 12 leagues of 1 goal from the hour pools, and a title.
do $check$ declare n bigint; t jsonb; s bigint:=floor(extract(epoch from now())/3600)::bigint; begin
 for n in s..s+500 loop t:=public.harvest_event_pick(n);
  if jsonb_array_length(t->'leagues')<>12 or exists(select 1 from jsonb_array_elements(t->'leagues') l where jsonb_array_length(l->'objectives')<>1 or coalesce(l->>'title','')=''
    or coalesce((l->'objectives'->0->>'target')::integer,0)<1 or coalesce(l->'objectives'->0->>'stat','') not in ('harvested','planted','watered','tended','fertilized','harvest_wheat','harvest_corn','harvest_lettuce','harvest_barley','made_eggs','made_feed','made_milk','made_cheese','made_flour','produced','made_grainmeal','made_bread','parallel_batches','made_salad','made_fertilizer','sold','earned','coins_spent','chores','activities','upgrades','activity_rounds','tractor','made_goatmilk','made_stone','made_ironore','made_timber','made_packedlunch','village_batches','made_plank','village_requests','lake_fish','made_clay','made_potatoes','made_rooftile')
    or (l->'objectives'->0->>'stat'='lake_fish' and (l->'objectives'->0->>'target')::integer>3)) then raise exception 'pick %',n; end if;
 end loop; end $check$;

-- 12. After-check, in the same transaction.
do $after$ declare fn text; want jsonb:='{"harvest_event_pick(bigint)":"a4354b4070af10908e1e609720cba26d","harvest_event_validate()":"15a89d91355e859133cecff10277a0fc","harvest_event_settle(uuid)":"1fd63cef297e5f96636fe7da62596b13","harvest_event_schedule()":"3d8632d66217916f3a9d18a74d340577","harvest_event_pause(timestamptz)":"ec48c1c17c8751f6ef231c9ac25b9f3e"}'; kept jsonb:='{"harvest_event_board(uuid)":["c509587a78de0cdc576cd6681ba9a29f"],"harvest_event_claim(uuid,uuid)":["de2cdc930a667bc9c80f3737fca9929c"],"harvest_event_league(integer)":["ea594ad4aeb110d5858de5cdaf68ddbe"],"harvest_event_league_for(integer,jsonb,smallint)":["72ba9cc06862bab8a5778cecd96fbaa7"],"harvest_event_progress()":["4681019789851e424d9a12f74f843077"]}'; begin
 for fn in select jsonb_object_keys(want) loop
  -- is distinct from: a missing function (NULL) fails too.
  if (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.'||fn)) is distinct from want->>fn then raise exception 'public.% did not come out as generated',fn; end if;
 end loop;
 for fn in select jsonb_object_keys(kept) loop
  if not (kept->fn ? coalesce((select md5(prosrc) from pg_proc where oid=to_regprocedure('public.'||fn)),'')) then raise exception 'public.% changed',fn; end if;
 end loop;
 -- The headers as live: security definer, volatility and search_path, then the grants.
 if exists(select 1 from (values ('harvest_event_board(uuid)',true,'s'),('harvest_event_settle(uuid)',false,'v'),('harvest_event_progress()',false,'v'),
    ('harvest_event_validate()',false,'v'),('harvest_event_pick(bigint)',false,'s'),('harvest_event_league(integer)',false,'i'),
    ('harvest_event_league_for(integer,jsonb,smallint)',false,'i'),('harvest_event_schedule()',false,'v'),('harvest_event_claim(uuid,uuid)',false,'v'),
    ('harvest_event_pause(timestamptz)',false,'v')) w(name,secdef,vol)
   left join pg_proc p on p.oid=to_regprocedure('public.'||w.name)
   where p.oid is null or p.prosecdef is distinct from w.secdef or p.provolatile::text is distinct from w.vol or p.proconfig is distinct from array['search_path=""'])
  then raise exception 'a function header changed (security definer, volatility or search_path)'; end if;
 if exists(select 1 from unnest(array['harvest_event_board(uuid)','harvest_event_settle(uuid)','harvest_event_progress()','harvest_event_validate()','harvest_event_pick(bigint)','harvest_event_schedule()']) as checked(name)
    where (select proacl::text from pg_proc where oid=to_regprocedure('public.'||checked.name)) is distinct from '{postgres=X/postgres,service_role=X/postgres}')
  or not has_function_privilege('service_role','public.harvest_event_pause(timestamptz)','execute')
  or has_function_privilege('anon','public.harvest_event_pause(timestamptz)','execute')
  or has_function_privilege('authenticated','public.harvest_event_pause(timestamptz)','execute')
  then raise exception 'the grants of a harvest_event function changed'; end if;
 if not (select relrowsecurity from pg_class where oid='public.event_config'::regclass)
  or has_table_privilege('anon','public.event_config','select') or has_table_privilege('authenticated','public.event_config','select')
  or (select count(*) from public.event_config)<>1 then raise exception 'event_config is not one private row'; end if;
 if (select pg_get_constraintdef(oid) from pg_constraint where conname='live_events_check' and conrelid='public.live_events'::regclass) not like '%00:30:00%'
  then raise exception 'live_events_check still asks an hour'; end if;
 if (select schedule from cron.job where jobname='harvest-event-schedule') is distinct from '*/5 * * * *' then raise exception 'the cron job does not run every 5 minutes'; end if;
 -- The events made ahead: hourly, with the prizes, 12 leagues and one goal each.
 if (select count(*) from public.live_events where created_by is null and starts_at>now() and active)<2 then raise exception 'fewer than 2 hourly events made ahead'; end if;
 if exists(select 1 from public.live_events e where e.created_by is null and e.starts_at>now()
    and (e.ends_at-e.starts_at<>interval '55 minutes' or not e.rewards ? 'podium' or e.rewards<>'{"coins":0,"diamondMin":1,"diamondMax":1,"participantStep":25,"poolCap":50,"podium":[8,5,3],"finisher":1,"familyFinishers":3,"familyDiamonds":3}'::jsonb or jsonb_array_length(e.leagues)<>12
     or exists(select 1 from jsonb_array_elements(e.leagues) l where jsonb_array_length(l->'objectives')<>1)))
  then raise exception 'an automatic event made ahead is not an hourly event'; end if;
 -- No 6-hour leftovers: none unsettled, none inactive from 20 Oct 2026.
 if exists(select 1 from public.live_events e where e.created_by is null and e.ends_at-e.starts_at>interval '55 minutes'
    and (e.settled_at is null or (not e.active and e.starts_at>='2026-10-20 12:00+00')))
  then raise exception 'a 6-hour automatic event is left'; end if;
end $after$;
commit;
